<script>
   function buscar(descargar=0){
       camara=document.getElementById("camara").value;
       desde=document.getElementById("desde").value;
       hasta=document.getElementById("hasta").value;
       persona_id=document.getElementById("persona_id").value;
       
       url='?page=accesos&buscar=1&camara='+camara+'&desde='+desde+'&hasta='+hasta+'&persona_id='+persona_id;
       if(descargar>0){
           url+="&descargar="+descargar;
       }
       location.href=url;
       
   } 
   
   
   
   
   scalado=false;
   ultimo_escalado="";
   function scale(img,id,mode){
       if(scalado){
           scalado=false;
           img=document.getElementById(id);
           img.style.transform = 'scale(1)';
           if(mode==1){
            img.setAttribute("style","position:relative;left:-10px;z-index:1");    
           }else{
            img.setAttribute("style","position:relative;left:30px;top:-40px;z-index:1");       
           }
           
       }else{
           ultimo_escalado=id;
           scalado=true;
           img.setAttribute("style","position:relative;left:-280px;z-index:99");
           img.style.transform = 'scale(10)';
       }
       
       
   }
   
    function sleep(ms) {
      return new Promise(resolve => setTimeout(resolve, ms));
    }
</script>